\title{TYTAN: Taylor-series based Non-Linear Activation Engine for Deep Learning Accelerators}

\titlerunning{TYTAN: Taylor-series based Non-Linear Activation Engine}

\author{Soham Pramanik\inst{1}\orcidID{0009-0005-1772-2901} \and
Vimal William\inst{2}\orcidID{0000-0002-1069-9594} \and
